@Component("adAccount-handler")
@ProcessingGroup("adAccount-processing-group")
public class AdAccountEventHandler {
	
	// core constructor
	AdAccountEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateAdAccountEvent
     */
    @EventHandler
    public void handle( CreateAdAccountEvent event) {
        entityManager.persist(new AdAccount(event.getAdAccountId(), event.getName(), event.getAccountCode(), event.getDefaultCurrency(), event.getDefaultTimezone(), event.getAdvertiser(), event.getUsers(), event.getCampaigns(), event.getBillingProfile(), event.getDsp(), event.getPerformanceMetrics()));
    }

    /*
     * @param	event UpdateAdAccountEvent
     */
    @EventHandler
    public AdAccount handle( UpdateAdAccountEvent event) {
    	entityManager.merge(new AdAccount(event.getAdAccountId(), event.getName(), event.getAccountCode(), event.getDefaultCurrency(), event.getDefaultTimezone(), event.getAdvertiser(), event.getUsers(), event.getCampaigns(), event.getBillingProfile(), event.getDsp(), event.getPerformanceMetrics()));
    }
    
    /*
     * @param	event DeleteAdAccountEvent
     */
    @EventHandler
    public void on( DeleteAdAccountEvent event) {
    	AdAccount entity = new AdAccount();
   
    	// ------------------------------------------
    	// apply the AdAccountId
    	// ------------------------------------------
    	entity.setAdAccountId( event.getAdAccountId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final AdAccountRepository adAccountEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(AdAccountEventHandler.class.getName());

}
